def check_distinct(test_tup):
    """Write a function to check if given tuple is distinct or not."""
    try:
        return len(set(test_tup)) == len(test_tup)
    except TypeError:
        # Some elements (e.g. lists) are unhashable and cannot be put
        # in a set; fall back to an equality-based scan.
        seen = []
        for item in test_tup:
            if item in seen:
                return False
            seen.append(item)
        return True
